# PyPortal display: clock, weather, schedule and photo gallery.
# Generated by PyPortal Display Designer. Layout, colors, fonts and timing
# live in /config.json; WiFi and the weather key live in /settings.toml.
# Written for CircuitPython 9.x on the Adafruit PyPortal (320x240).
import gc
import json
import os
import time

import board
import busio
import displayio
import rtc
import vectorio
from digitalio import DigitalInOut
from adafruit_bitmap_font import bitmap_font
from adafruit_display_text import bitmap_label

with open("/config.json") as fp:
    CFG = json.load(fp)

display = board.DISPLAY
try:
    display.brightness = CFG.get("brightness", 1.0)
except Exception:  # some builds have no brightness control
    pass

WEEKDAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
MONTHS = ("January", "February", "March", "April", "May", "June", "July",
          "August", "September", "October", "November", "December")
ANCHOR_X = {"left": 0.0, "center": 0.5, "right": 1.0}

# ---------------------------------------------------------------- helpers

_fonts = {}


def get_font(name):
    if name not in _fonts:
        _fonts[name] = bitmap_font.load_font("/fonts/" + name)
    return _fonts[name]


def text_width(font, text):
    width = 0
    for ch in text:
        glyph = font.get_glyph(ord(ch))
        if glyph:
            width += glyph.shift_x
    return width


def fit_text(font, text, max_width):
    if max_width <= 0 or text_width(font, text) <= max_width:
        return text
    while text and text_width(font, text + "...") > max_width:
        text = text[:-1]
    return text.rstrip() + "..."


def fill(template, values):
    for key in values:
        template = template.replace("{" + key + "}", str(values[key]))
    return template


def fmt_time(hour, minute, second=None, hour24=False, ampm=True):
    if hour24:
        out = "%02d:%02d" % (hour, minute)
    else:
        out = "%d:%02d" % ((hour % 12) or 12, minute)
    if second is not None:
        out += ":%02d" % second
    if not hour24 and ampm:
        out += " AM" if hour < 12 else " PM"
    return out


def date_values(now):
    return {
        "weekday": WEEKDAYS[now.tm_wday],
        "wkd": WEEKDAYS[now.tm_wday][:3],
        "month": MONTHS[now.tm_mon - 1],
        "mon": MONTHS[now.tm_mon - 1][:3],
        "day": now.tm_mday,
        "mm": "%02d" % now.tm_mon,
        "dd": "%02d" % now.tm_mday,
        "year": now.tm_year,
    }


def make_label(el, text=""):
    # Anchor on the text baseline (y = -1.0) so placement matches the designer
    # pixel for pixel: the designer's y is the top of the font's ascent.
    font = get_font(el["font"])
    label = bitmap_label.Label(font, text=text, color=el["color"])
    label.anchor_point = (ANCHOR_X.get(el.get("align", "left"), 0.0), -1.0)
    label.anchored_position = (el["x"], el["y"] + font.ascent)
    return label


def set_text(label, text):
    if label.text != text:
        label.text = text


def solid_rect(color, x, y, width, height):
    palette = displayio.Palette(1)
    palette[0] = color
    return vectorio.Rectangle(pixel_shader=palette, x=x, y=y, width=width, height=height)


def bitmap_tile(path):
    bmp = displayio.OnDiskBitmap(path)
    return displayio.TileGrid(bmp, pixel_shader=bmp.pixel_shader)


# ---------------------------------------------------------------- screen

main_group = displayio.Group()
background = CFG["background"]
if background.get("image"):
    main_group.append(bitmap_tile("/images/" + background["image"]))
else:
    main_group.append(solid_rect(background["color"], 0, 0, display.width, display.height))

clock_labels = []      # (label, element)
date_labels = []
weather_labels = []
updated_labels = []
schedule_widgets = []  # (element, rows) where rows = [(time_label, text_label)]

for el in CFG["elements"]:
    if not el.get("visible", True):
        continue
    kind = el["type"]
    if kind == "schedule":
        if el.get("box"):
            pad = el.get("boxPad", 4)
            main_group.append(solid_rect(el["boxColor"], el["x"] - pad, el["y"] - pad,
                                         el["width"] + 2 * pad, el["boxHeight"] + 2 * pad))
        rows = []  # one line per entry: days, time, text
        for i in range(el["rows"]):
            y = el["y"] + i * el["rowHeight"]
            row = (make_label({"font": el["font"], "color": el["timeColor"], "x": el["x"], "y": y}),
                   make_label({"font": el["font"], "color": el["timeColor"],
                               "x": el["x"] + el.get("daysWidth", 0), "y": y}),
                   make_label({"font": el["font"], "color": el["color"],
                               "x": el["x"] + el["timeWidth"], "y": y}))
            for label in row:
                main_group.append(label)
            rows.append(row)
        schedule_widgets.append((el, rows))
        continue
    label = make_label(el, el.get("text", "") if kind == "text" else "")
    main_group.append(label)
    if kind == "clock":
        clock_labels.append((label, el))
    elif kind == "date":
        date_labels.append((label, el))
    elif kind == "temp":
        weather_labels.append((label, el))
    elif kind == "updated":
        updated_labels.append((label, el))

gallery_cfg = CFG["gallery"]
gallery_images = gallery_cfg["images"]
gallery_group = None
if gallery_images:
    gallery_group = displayio.Group()
    gallery_group.append(bitmap_tile("/images/" + gallery_images[0]["file"]))
    overlay = gallery_cfg.get("overlay")
    if overlay and overlay.get("visible"):
        clock_labels.append((make_label(overlay), overlay))
        gallery_group.append(clock_labels[-1][0])

display.root_group = main_group

# ---------------------------------------------------------------- WiFi + weather

SSID = os.getenv("CIRCUITPY_WIFI_SSID")
PASSWORD = os.getenv("CIRCUITPY_WIFI_PASSWORD")
OWM_KEY = os.getenv("OPENWEATHER_KEY")
ZIP_CODE = os.getenv("WEATHER_ZIP") or CFG["weather"]["zip"]
COUNTRY = os.getenv("WEATHER_COUNTRY") or CFG["weather"].get("country", "US")
UNITS = CFG["weather"].get("units", "imperial")

esp = None
requests = None
if SSID and OWM_KEY:
    from adafruit_esp32spi import adafruit_esp32spi
    import adafruit_connection_manager
    import adafruit_requests

    esp32_cs = DigitalInOut(board.ESP_CS)
    esp32_ready = DigitalInOut(board.ESP_BUSY)
    esp32_reset = DigitalInOut(board.ESP_RESET)
    spi = busio.SPI(board.SCK, board.MOSI, board.MISO)
    esp = adafruit_esp32spi.ESP_SPIcontrol(spi, esp32_cs, esp32_ready, esp32_reset)
    pool = adafruit_connection_manager.get_radio_socketpool(esp)
    ssl_context = adafruit_connection_manager.get_radio_ssl_context(esp)
    requests = adafruit_requests.Session(pool, ssl_context)
else:
    print("No WiFi or OPENWEATHER_KEY in settings.toml: running offline")


def wifi_ok():
    if esp.is_connected:
        return True
    try:
        print("Connecting to", SSID)
        esp.connect_AP(SSID, PASSWORD)
        return True
    except Exception as err:  # pylint: disable=broad-except
        print("WiFi failed:", err)
        return False


def parse_http_date(value):
    # "Fri, 16 Oct 2026 17:40:15 GMT" -> seconds since 1970 (UTC)
    parts = value.split()
    hh, mm, ss = [int(p) for p in parts[4].split(":")]
    month = [m[:3] for m in MONTHS].index(parts[2]) + 1
    return time.mktime(time.struct_time((int(parts[3]), month, int(parts[1]),
                                         hh, mm, ss, 0, -1, -1)))


weather = {"temp": "--", "feels": "--", "hi": "--", "lo": "--", "desc": "",
           "main": "", "humidity": "--", "wind": "--", "city": "",
           "unit": "°F" if UNITS == "imperial" else "°C"}
last_update = None  # struct_time of the last good fetch
clock_set = False


def fetch_weather():
    global last_update, clock_set
    url = ("https://api.openweathermap.org/data/2.5/weather?zip=%s,%s&units=%s&appid=%s"
           % (ZIP_CODE, COUNTRY, UNITS, OWM_KEY))
    response = requests.get(url, timeout=20)
    try:
        date_header = None
        for key, value in response.headers.items():
            if isinstance(key, bytes):
                key, value = key.decode(), value.decode()
            if key.lower() == "date":
                date_header = value
        data = response.json()
    finally:
        response.close()
    if str(data.get("cod")) != "200":
        raise RuntimeError("OpenWeatherMap: %s" % data.get("message"))
    # Set the clock from the server time plus the zip code's UTC offset.
    offset = data.get("timezone", 0)
    try:
        utc = parse_http_date(date_header) if date_header else data["dt"]
    except Exception:  # pylint: disable=broad-except
        utc = data["dt"]
    rtc.RTC().datetime = time.localtime(utc + offset)
    clock_set = True
    m = data["main"]
    desc = data["weather"][0]["description"] if data.get("weather") else ""
    weather.update({
        "temp": round(m["temp"]),
        "feels": round(m.get("feels_like", m["temp"])),
        "hi": round(m.get("temp_max", m["temp"])),
        "lo": round(m.get("temp_min", m["temp"])),
        "humidity": m.get("humidity", "--"),
        "desc": desc[:1].upper() + desc[1:],
        "main": data["weather"][0]["main"] if data.get("weather") else "",
        "wind": round(data.get("wind", {}).get("speed", 0)),
        "city": data.get("name", ""),
    })
    last_update = time.localtime()


# ---------------------------------------------------------------- updates

# Weekly schedule: one line per entry ("MTWTF  6:40am  In DRL until 1:40pm").
# Days are 0 = Monday ... 6 = Sunday. Entries are "time" (at a time), "range"
# (from a time until an end time) or "allday".
DAY_LETTERS = "MTWTFSS"
SCHEDULE = [e for e in CFG["schedule"]["entries"] if e.get("days")]


def short_time(minute, hour24=False):
    hour, minute = (minute // 60) % 24, minute % 60
    if hour24:
        return "%02d:%02d" % (hour, minute)
    return "%d:%02d%s" % ((hour % 12) or 12, minute, "am" if hour < 12 else "pm")


def update_weather_labels():
    for label, el in weather_labels:
        set_text(label, fill(el["format"], weather))
    for label, el in updated_labels:
        if last_update is None:
            text = el.get("pending", "Updating...")
        else:
            stamp = fmt_time(last_update.tm_hour, last_update.tm_min,
                             hour24=el.get("hour24", False))
            text = fill(el["format"], {"time": stamp})
        set_text(label, text)


def update_clock(now):
    for label, el in clock_labels:
        sec = now.tm_sec if el.get("seconds") else None
        set_text(label, fmt_time(now.tm_hour, now.tm_min, sec,
                                 el.get("hour24", False), el.get("ampm", True)))
    values = date_values(now)
    for label, el in date_labels:
        set_text(label, fill(el["format"], values))


def schedule_lines(el, now):
    # [(days, time, text, happening_now)] for the first el["rows"] entries.
    wday = now.tm_wday
    now_min = now.tm_hour * 60 + now.tm_min
    h24 = el.get("hour24", False)
    lines = []
    for e in SCHEDULE[:el["rows"]]:
        kind = e.get("kind", "time")
        start, end = e["m"], e.get("end") or 0
        days = "Daily" if len(e["days"]) == 7 else "".join(DAY_LETTERS[d] for d in sorted(e["days"]))
        when = "All day" if kind == "allday" else short_time(start, h24)
        what = e["text"] + " until " + short_time(end, h24) if kind == "range" else e["text"]
        hot = False
        if wday in e["days"]:
            if kind == "allday":
                hot = True
            elif kind == "range":
                if end > start:
                    hot = start <= now_min < end
                else:  # runs past midnight
                    hot = now_min >= start or now_min < end
        lines.append((days, when, what, hot))
    return lines


def update_schedule(now):
    for el, rows in schedule_widgets:
        lines = schedule_lines(el, now)
        font = get_font(el["font"])
        max_text = el["width"] - el["timeWidth"]
        for i, (days_label, time_label, text_label) in enumerate(rows):
            if i < len(lines):
                days, when, what, is_now = lines[i]
                hot = el.get("highlight") and is_now
                set_text(days_label, days)
                set_text(time_label, when)
                set_text(text_label, fit_text(font, what, max_text))
                days_label.color = time_label.color = el["highlightColor"] if hot else el["timeColor"]
                text_label.color = el["highlightColor"] if hot else el["color"]
            else:
                for label in (days_label, time_label, text_label):
                    set_text(label, "")


SCHEDULE_SECONDS = CFG["timing"]["scheduleSeconds"]
WEATHER_SECONDS = CFG["timing"]["weatherMinutes"] * 60

mode = "schedule"
mode_until = time.monotonic() + SCHEDULE_SECONDS
image_index = 0
next_weather = 0
last_second = -1
last_minute = -1

update_weather_labels()

while True:
    now_mono = time.monotonic()

    if requests and now_mono >= next_weather:
        next_weather = now_mono + WEATHER_SECONDS
        try:
            if wifi_ok():
                fetch_weather()
        except Exception as err:  # pylint: disable=broad-except
            print("Weather update failed:", err)
            next_weather = now_mono + 60  # try again in a minute
        update_weather_labels()
        last_minute = -1
        gc.collect()
        now_mono = time.monotonic()

    now = time.localtime()
    if now.tm_sec != last_second:
        last_second = now.tm_sec
        update_clock(now)
        if now.tm_min != last_minute:
            last_minute = now.tm_min
            update_schedule(now)

    if gallery_group and now_mono >= mode_until:
        if mode == "schedule":
            mode = "gallery"
            image_index = 0
        else:
            image_index += 1
        if image_index >= len(gallery_images):
            mode = "schedule"
            display.root_group = main_group
            mode_until = now_mono + SCHEDULE_SECONDS
        else:
            entry = gallery_images[image_index]
            gallery_group[0] = bitmap_tile("/images/" + entry["file"])
            display.root_group = gallery_group
            mode_until = now_mono + entry["seconds"]
        gc.collect()

    time.sleep(0.1)
